 private void orientationControls(){
  title("Orientación y control del recorrido");
  button("Vista general de la figura",()->{freezeImageForExploration();transport("pause",(imageActive?"Contornos extraídos por contraste: ":"Geometría generada: ")+Orientation.overview(geometry));record("overview",null);});
  button("Dónde dejé el puntero",()->{String s=Orientation.at(geometry,orientationPoint);transport("pause",s);});
  String[] labels={"Pausar recorrido","Continuar recorrido","Retroceder cinco segundos y pausar","Guardar marcador y pausar","Volver al marcador","Repetir últimos cinco segundos","Dónde estoy en el recorrido"};
  String[] commands={"pause","resume","back","mark","return","fragment","position"};
  for(int i=0;i<labels.length;i++){final String command=commands[i];button(labels[i],()->transport(command,null));}
  paragraph("La pausa conserva el recorrido y su marcador. Después de retroceder o consultar la posición, pulsa Continuar. Repetir reproduce los últimos cinco segundos y pausa al llegar al punto original. Si estás al inicio, reproduce los primeros cinco segundos. Detener, cambiar de escena o tocar el lienzo cancela el recorrido guardado.");
 }
 private void transport(String command,String override){
  if(tts!=null)tts.stop();afterSpeech.clear();
  audio.control(command,message->handler.post(()->{String s=override==null?message:override;say(s);if(!command.equals("resume")&&!command.equals("fragment")){releaseAudioFocus();if(narration)speak(s,null);}}));
  if(command.equals("resume")||command.equals("fragment"))requestAudioFocus();
  record("playback_"+command,null);
 }
