 private void speak(String message,Runnable then){if(!ttsReady){say(message+" Voz no disponible; puedes leerla con TalkBack.");if(then!=null)then.run();return;}String id=Long.toString(utterance.incrementAndGet());if(then!=null)afterSpeech.put(id,then);int result=tts.speak(message,TextToSpeech.QUEUE_FLUSH,null,id);if(result==TextToSpeech.ERROR){afterSpeech.remove(id);if(then!=null)then.run();}}
 private void cancelPlayback(){if(audio!=null)audio.stop();if(tts!=null)tts.stop();afterSpeech.clear();releaseAudioFocus();}
 private AudioFocusRequest focus;
 private void releaseAudioFocus(){if(focus!=null)((AudioManager)getSystemService(AUDIO_SERVICE)).abandonAudioFocusRequest(focus);}
 private void requestAudioFocus(){AudioManager m=(AudioManager)getSystemService(AUDIO_SERVICE);if(focus==null)focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT_MAY_DUCK).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_GAME).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS||change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT)handler.post(()->{audio.control("pause",null);if(tts!=null)tts.stop();afterSpeech.clear();say("En pausa por interrupción de audio. Puedes continuar desde Orientación.");});}).build();m.requestAudioFocus(focus);}
 private void say(String message){if(status!=null)status.setText(message);}
 private void settingsChanged(){audio.settings(sound);savePreferences();record("sound_settings",settingsData());}
 private void loadPreferences(){imageOptions.mode=prefs.getInt("imageMode",0);imageOptions.offset=prefs.getInt("imageOffset",0);imageOptions.edgeThreshold=prefs.getInt("imageEdge",70);imageOptions.maxDimension=prefs.getInt("imageResolution",192);imageOptions.minArea=prefs.getInt("imageArea",8);imageOptions.maxContours=prefs.getInt("imageContours",12);imageOptions.detail=prefs.getFloat("imageDetail",1.5f);showOriginal=prefs.getBoolean("showOriginal",true);guideIndex=Curriculum.clamp(prefs.getInt("guideIndex",0));guideVariant=prefs.getInt("guideVariant",0);surface=prefs.getInt("surface",0);filter=prefs.getInt("filter",0);anchor=prefs.getInt("anchor",4);separation=prefs.getFloat("separation",70);tolerance=prefs.getFloat("tolerance",18);air=prefs.getBoolean("air",true);haptics=prefs.getBoolean("haptics",true);sound.lowHz=prefs.getFloat("lowHz",180);sound.highHz=prefs.getFloat("highHz",720);sound.profile=prefs.getInt("profile",0);sound.spatial=prefs.getInt("spatial",1);sound.monoLateral=prefs.getBoolean("monoLateral",true);sound.monoAmount=prefs.getFloat("monoAmount",.7f);sound.volume=prefs.getFloat("volume",.28f);sound.width=prefs.getFloat("width",65);sound.elevation=prefs.getFloat("elevation",35);sound.pitch=prefs.getFloat("pitch",.65f);sound.speed=prefs.getFloat("speed",1);sound.pause=prefs.getFloat("pause",.18f);sound.brightness=prefs.getFloat("brightness",.6f);sound.markers=prefs.getBoolean("markers",true);sound.swap=prefs.getBoolean("swap",false);narration=prefs.getBoolean("narration",true);hide=prefs.getBoolean("hide",false);family=prefs.getInt("family",0);level=prefs.getInt("level",0);}
 private void savePreferences(){prefs.edit().putInt("imageMode",imageOptions.mode).putInt("imageOffset",imageOptions.offset).putInt("imageEdge",imageOptions.edgeThreshold).putInt("imageResolution",imageOptions.maxDimension).putInt("imageArea",imageOptions.minArea).putInt("imageContours",imageOptions.maxContours).putFloat("imageDetail",(float)imageOptions.detail).putBoolean("showOriginal",showOriginal).putInt("guideIndex",guideIndex).putInt("guideVariant",guideVariant).putInt("surface",surface).putInt("filter",filter).putInt("anchor",anchor).putFloat("separation",(float)separation).putFloat("tolerance",(float)tolerance).putBoolean("air",air).putBoolean("haptics",haptics).putFloat("lowHz",(float)sound.lowHz).putFloat("highHz",(float)sound.highHz).putInt("profile",sound.profile).putInt("spatial",sound.spatial).putBoolean("monoLateral",sound.monoLateral).putFloat("monoAmount",(float)sound.monoAmount).putFloat("volume",(float)sound.volume).putFloat("width",(float)sound.width).putFloat("elevation",(float)sound.elevation).putFloat("pitch",(float)sound.pitch).putFloat("speed",(float)sound.speed).putFloat("pause",(float)sound.pause).putFloat("brightness",(float)sound.brightness).putBoolean("markers",sound.markers).putBoolean("swap",sound.swap).putBoolean("narration",narration).putBoolean("hide",hide).putInt("family",family).putInt("level",level).apply();}
