 private JSONObject settingsData(){JSONObject d=object("spatial",sound.spatial==3?"openal-hrtf":sound.spatial==2?"mono-code":sound.spatial==1?"kemar-hrtf":"stereo");put(d,"audioBackend",audio.backend);put(d,"monoLateral",sound.monoLateral);put(d,"monoAmount",sound.monoAmount);put(d,"width",sound.width);put(d,"elevation",sound.elevation);put(d,"pitch",sound.pitch);put(d,"speed",sound.speed);put(d,"pause",sound.pause);put(d,"brightness",sound.brightness);put(d,"volume",sound.volume);put(d,"markers",sound.markers);put(d,"swap",sound.swap);put(d,"lowHz",sound.lowHz);put(d,"highHz",sound.highHz);put(d,"surface",surface);put(d,"filter",filter);put(d,"anchor",anchor);put(d,"air",air);put(d,"haptics",haptics);put(d,"tolerance",tolerance);put(d,"separation",separation);return d;}
 private JSONObject geometryData(){JSONObject d=object("family",geometry.family);JSONArray shapes=new JSONArray();for(Geometry.Shape shape:geometry.shapes){JSONObject s=object("closed",shape.closed);put(s,"curve",shape.curve);put(s,"strokeWidth",shape.strokeWidth);put(s,"hole",shape.hole);JSONArray points=new JSONArray();for(Geometry.Point p:shape.points)points.put(new JSONArray(Arrays.asList(p.x,p.y,p.z)));put(s,"points",points);shapes.put(s);}put(d,"shapes",shapes);put(d,"settings",settingsData());return d;}
 private void record(String type,JSONObject detail){JSONObject e=object("type",type);put(e,"t",SystemClock.elapsedRealtime()-sessionStart);put(e,"trial",trial);put(e,"seed",imageActive?"external":geometry==null?"0":Long.toString(geometry.seed));put(e,"mode",imageActive?"image":guided||screen.equals("Guía")?"guided":new String[]{"free","learn","quiz","hunt"}[mode]);if(!imageActive)put(e,"lesson",Curriculum.LESSONS.get(Curriculum.clamp(guideIndex)).id);else{put(e,"sourceId",imageId);put(e,"analysisId",analysisId);}put(e,"variant",guideVariant);put(e,"separation",separation);put(e,"profile",new String[]{"soft","string","retro"}[sound.profile]);put(e,"level",level);put(e,"audioVersion","0.10.0");if(detail!=null){Iterator<String> keys=detail.keys();while(keys.hasNext()){String key=keys.next();put(e,key,detail.opt(key));}}events.put(e);saveSession();}
 private void saveSession(){try{JSONObject out=object("id",sessionId);put(out,"events",events);try(FileOutputStream stream=openFileOutput("session.tmp",MODE_PRIVATE)){stream.write(out.toString().getBytes(StandardCharsets.UTF_8));}if(!new File(getFilesDir(),"session.tmp").renameTo(new File(getFilesDir(),"session.json")))say("No se pudo guardar la sesión.");}catch(Exception e){say("No se pudo guardar la sesión. Exporta antes de cerrar.");}}
